"朱峰社区无限":"ZF3D AGENT",
"访问朱峰智能体网站":"Visit zf3d.com",
"设置 / 模型配置":"Settings / Model Config",
"文件树录音、录屏功能依赖的音频与屏幕选区组件（soundcard、numpy、tk 等）。默认不随程序携带，安装后即可使用。":"File tree: audio/screen-recording features depend on audio and screen-capture components (soundcard, numpy, tk, etc.). Not bundled by default; install them to enable.",
"将所有设置（模型线路、用户设置、用户习惯、对话模式、工具限额、扩展设置等）导出为一个 JSON 文件，\n                        丢失设置后可通过导入一键找回。":"Export all settings (model routes, user settings, habits, dialog modes, tool limits, extensions, etc.) to a JSON file. If settings are lost, import it to restore everything in one click.",
"这个项目，诞生于它的上一个版本。最开始我们只做了三个工具：读取、写入、执行。经过几天时间，就创建了如此好用的朱峰社区无限！":"This project was born from its previous version. We started with just three tools: Read, Write, Execute. Within days, the powerful ZF3D AGENT was created!",
"开发速度是惊人的，朱峰老师几乎同时可以操作至少 8–30 个窗口，以超级惊人的速度进行任务执行工作。朱峰智能体智能体绝对是干活效率领先的智能体头部产品！":"Development speed is astonishing — ZhuFeng operates 8-30+ windows simultaneously, executing tasks at incredible speed. ZF3D AGENT is truly a top-tier agent product for productivity!",
"免费开源 · 支持多模型多对话 · Windows / Web 双端 · 零依赖启动（纯 Python 标准库，双击即用）。":"Free & open source · Multi-model & multi-dialog · Windows / Web · Zero-dependency startup (pure Python stdlib, double-click to run).",
"右键创建对话框，中键拖拽平移，随意缩放。小地图导航，双击展开菜单，任意创建会话，超级快。自由组织对话节点，哪个优先做、哪个之后做一目了然，最多可同时开启 400+ 个任务对话窗口。":"Right-click to create dialogs, middle-drag to pan, zoom freely. Minimap navigation, double-click to expand menus, create sessions instantly. Organize dialog nodes freely — priorities at a glance, up to 400+ task dialogs open at once.",
"我不属于任何模型，每个会话走最佳线路。DeepSeek、通义千问、智谱GLM、豆包、Kimi、GPT、Claude、Gemini、腾讯混元、百度文心、本地Ollama，任意 OpenAI 兼容接口，哪个最强走哪个。":"I'm not tied to any single model — each session takes the best route. DeepSeek, Qwen, Zhipu GLM, Doubao, Kimi, GPT, Claude, Gemini, Hunyuan, ERNIE, local Ollama — any OpenAI-compatible API. Whatever is strongest gets used.",
"AI不只是聊天。Agent 工具循环，让 AI 自主读写文件、运行代码、联网抓取、Git提交、定时调度、跨对话搜索、发邮件、管理记忆、向你提问。极简 29 / 编程 33 / 写作 58，三模式按需切换。":"AI is more than chat. The Agent tool loop lets AI read/write files, run code, fetch the web, commit to Git, schedule tasks, search across dialogs, send email, manage memory, and ask you questions. Minimal 29 / Coding 33 / Writing 58 — switch modes as needed.",
"零依赖，纯 Python 标准库，双击即用。前后端分离，热更新改完即生效。模块化架构，app.js 拆 10 模块、server.py 拆 7 模块。":"Zero dependencies, pure Python stdlib, double-click to run. Front/back-end separated with hot reload. Modular architecture: app.js split into 10 modules, server.py into 7.",
"打开设置 → 模型管理，填入任一 OpenAI 兼容接口的 Base URL 和 API Key（DeepSeek、智谱、Kimi、本地 Ollama 均可），密钥只存本机。":"Open Settings → Model management, enter the Base URL and API Key of any OpenAI-compatible API (DeepSeek, Zhipu, Kimi, local Ollama all work). Keys stay on your machine only.",
"用风筝系统（monitor/chat_manage）把任务分派给其他对话，主对话守护监控并回收结果；也可以 shift+移动对话框复制会话做 A/B 对照。":"Use the Kite system (monitor/chat_manage) to dispatch tasks to other dialogs; the main dialog supervises and collects results. Or shift+drag a dialog to copy a session for A/B comparison.",
"大文件模块化拆分（app.js→10 模块、server.py→7 模块、style.css→5 模块）；新增 14 个工具（replace_text、tree_dir、find_files、search_in_files、schedule、project_record、search_chat、chat_context、chat_summary、monitor、task_list 等）；小地图导航系统；消息队列系统；工具消息折叠；画布中键拖拽平移；对话标题自动更新；修复事件监听器泄漏。":"Modular split of large files (app.js→10 modules, server.py→7, style.css→5); 14 new tools (replace_text, tree_dir, find_files, search_in_files, schedule, project_record, search_chat, chat_context, chat_summary, monitor, task_list, etc.); minimap navigation; message queue; tool message collapsing; middle-drag canvas panning; auto dialog titles; fixed event listener leaks.",
"前后台分离架构 + SQLite 持久化（7 张表 WAL 模式）；Agent 工具循环（最大深度 10）+ API 代理解决 CORS；新增 8 个基础工具；后台离线自动回退 localStorage。":"Front/back-end separation + SQLite persistence (7 tables, WAL mode); Agent tool loop (max depth 10) + API proxy to solve CORS; 8 new basic tools; offline fallback to localStorage.",
"联网能力、API 密钥、额度和模型可用性由服务商决定。API 密钥不要写入对话、脚本、日志或截图。运行命令、修改文件、发送邮件前确认目标和范围，重要资料先备份，并明确限定允许访问的文件夹。发现目标不正确时立即暂停任务并要求停止。":"Connectivity, API keys, quotas and model availability depend on providers. Never put API keys in dialogs, scripts, logs or screenshots. Confirm targets and scope before running commands, modifying files or sending email; back up important data and clearly limit accessible folders. Pause and ask to stop immediately if the target looks wrong.",
"免费模型不代表一定无需密钥；401、额度或网络错误通常需要检查接口和服务状态。API 密钥不要写入对话、脚本或截图。运行命令、修改文件、发送邮件前确认目标和范围，重要资料先备份。":"Free models may still require keys; 401, quota or network errors usually mean checking the API and service status. Never put API keys in dialogs, scripts or screenshots. Confirm targets and scope before running commands, modifying files or sending email; back up important data.",
"本应用支持一键保存到 Gitee/GitHub 远程仓库。先在这里了解它们是什么、如何选择，再前往「保存/发布」配置仓库地址。":"This app supports one-click push to Gitee/GitHub remotes. Learn what they are and how to choose here, then configure the repo URL in \"Save/Publish\".",
"📜 长任务":"📜 Long Tasks",
"风筝系统开关：点开显示风筝，点关隐藏风筝":"Kite system toggle: click on to show the kite, click off to hide it",
"https://gitee.com/用户名/仓库名.git":"https://gitee.com/username/repo.git",
