"超快，超级大，大了自己分割。每 5 秒自动保存你的数据，对话永不丢失。后台离线自动回退本地存储，恢复后无缝切回。":"Super fast, super large, self-splitting. Auto-saves every 5 seconds — dialogs never lost. Falls back to local storage offline and switches back seamlessly.",
