'本地 AI 推理功能依赖（较大，约 200MB，不需要可跳过）':'Abhängigkeit der nativen KI-Inferenzfunktion (größer, ca. 200 MB, kein Überspringen erforderlich)',
'语言模型：你可以创建一个大模型设置，连通到该模型后直接和它进行对话。可用于聊天、智能体和工具调用，建议选择 GLM-5.3-Flash——目前很划算，速度也很快。':'Sprachmodell: Sie können ein großes Modell-Setup erstellen und sich mit dem Modell verbinden, um direkt mit ihm zu sprechen. GLM-5.3-Flash ist für Chat-, Agenten- und Tool-Anrufe verfügbar und wird empfohlen - es ist jetzt kostengünstig und schnell.',
'向量化模型：方便搜索的模型种类，可将文本转为向量，用于知识库检索、语义搜索和相似度匹配，是快速搜索知识库的底层支撑。':'Vektorisiertes Modell: Eine Art von Modell, das die Suche erleichtert. Es kann Text in Vektoren für den Abruf von Wissensdatenbanken, die semantische Suche und den Abgleich von Ähnlichkeiten konvertieren. Es ist die zugrunde liegende Unterstützung für die schnelle Suche in der Wissensdatenbank.',
'识图模型：可以"看清"图片和视频的具体内容，理解画面中的物体、文字与场景，常用于图片问答与内容分析。':'Mapping-Modell: Es kann den spezifischen Inhalt von Bildern und Videos „sehen“, die Objekte, Texte und Szenen im Bild verstehen und wird häufig für die Beantwortung von Bildfragen und die Inhaltsanalyse verwendet.',
'把游戏引擎、内置浏览器、演示 PPT 三个顶栏入口收进一个下拉菜单，节省顶栏宽度。':'Speichern Sie die Breite der oberen Leiste, indem Sie die drei Eingänge der oberen Leiste der Spiel-Engine, den integrierten Browser und die Demo-PPT in ein Dropdown-Menü aufnehmen.',
