'语言模型：你可以创建一个大模型设置，连通到该模型后直接和它进行对话。可用于聊天、智能体和工具调用，建议选择 GLM-5.3-Flash——目前很划算，速度也很快。':'Modelo de lenguaje: puede crear una configuración de modelo grande y conectarse al modelo para hablar con él directamente. Disponible para llamadas de chat, agentes y herramientas, se recomienda GLM-5.3-Flash: es rentable y rápido en este momento.',
'向量化模型：方便搜索的模型种类，可将文本转为向量，用于知识库检索、语义搜索和相似度匹配，是快速搜索知识库的底层支撑。':'Modelo vectorizado: un tipo de modelo que facilita la búsqueda. Puede convertir el texto en vectores para la recuperación de la base de conocimientos, la búsqueda semántica y la coincidencia de similitudes. Es el soporte subyacente para la búsqueda rápida de la base de conocimientos.',
'识图模型：可以"看清"图片和视频的具体内容，理解画面中的物体、文字与场景，常用于图片问答与内容分析。':'Modelo de mapeo: puede "ver" el contenido específico de imágenes y videos, comprender los objetos, textos y escenas de la imagen y, a menudo, se utiliza para responder preguntas de imágenes y analizar el contenido.',
