'语言模型：你可以创建一个大模型设置，连通到该模型后直接和它进行对话。可用于聊天、智能体和工具调用，建议选择 GLM-5.3-Flash——目前很划算，速度也很快。':'نموذج اللغة: يمكنك إنشاء إعداد نموذج كبير والاتصال بالنموذج للتحدث إليه مباشرة. متاح لمكالمات الدردشة والوكيل والأدوات، يوصى باستخدام GLM-5.3 - Flash - إنه فعال من حيث التكلفة وسريع في الوقت الحالي.',
'向量化模型：方便搜索的模型种类，可将文本转为向量，用于知识库检索、语义搜索和相似度匹配，是快速搜索知识库的底层支撑。':'النموذج المتجهي: نوع من النماذج التي تسهل البحث، يمكنه تحويل النص إلى متجهات لاسترجاع قاعدة المعرفة، والبحث الدلالي، ومطابقة التشابه، وهو الدعم الأساسي للبحث السريع في قاعدة المعرفة.',
'识图模型：可以"看清"图片和视频的具体内容，理解画面中的物体、文字与场景，常用于图片问答与内容分析。':'نموذج رسم الخرائط: يمكنه "رؤية" المحتوى المحدد للصور ومقاطع الفيديو، وفهم الكائنات والنصوص والمشاهد في الصورة، وغالبًا ما يستخدم للإجابة على أسئلة الصور وتحليل المحتوى.',
'把游戏引擎、内置浏览器、演示 PPT 三个顶栏入口收进一个下拉菜单，节省顶栏宽度。':'احفظ عرض الشريط العلوي من خلال تضمين مداخل الشريط العلوي الثلاثة لمحرك اللعبة، والمتصفح المدمج، و PPT التجريبي في قائمة منسدلة.',
